<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\TruckService;use App\Support\Url;Auth::requirePermission('TRUCK_REVIEW_QUEUE_VIEW');$rows=TruckService::reviewQueue();$pageTitle='Truck Verification Queue';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Truck verification queue</h1><p>Pending truck, insurance, inspection, and roadworthiness reviews.</p></div><span class="badge"><?=h(count($rows))?> pending</span></div><div class="card table-wrap"><table><thead><tr><th>Registration</th><th>Owner</th><th>Truck</th><th>Capacity</th><th>Insurance</th><th>Inspection</th><th></th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['registration_number'].' · '.$r['registration_country'])?></td><td><?=h($r['owner_company_name']?:$r['owner_user_name'])?></td><td><?=h($r['make_name'].' '.$r['model_name'].' · '.str_replace('_',' ',$r['body_type_code']))?></td><td><?=h($r['capacity_value'].' '.$r['capacity_unit'])?></td><td><?=h($r['insurance_valid_to'])?></td><td><?=h($r['result_code'].' · '.$r['roadworthiness_status'].' · '.$r['inspection_expires_on'])?></td><td><a href="<?=h(Url::to('operations/truck-review.php?id='.$r['verification_case_id']))?>">Review</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="muted">No pending truck verifications.</td></tr><?php endif;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
